  /** Registered At: When the domain was registered or WHOIS entry was created. (optional) */
  created_time_dt?: string;
  /** DNSSEC Status: The normalized value of dnssec_status_id. (optional) */
  dnssec_status?: string;
  /** DNSSEC Status ID: Describes the normalized status of DNS Security Extensions (DNSSEC) for a domain. Values: 0 Unknown, 1 Signed, 2 Unsigned, 99 Other. (recommended) */
  dnssec_status_id?: 0 | 1 | 2 | 99;
  /** Domain: The domain name corresponding to the WHOIS record. (recommended) */
  domain?: string;
  /** Domain Contacts: An array of Domain Contact objects. (recommended) */
  domain_contacts?: OcsfDomainContact[];
  /** Registrar Abuse Email Address: The email address for the registrar's abuse contact (optional) */
  email_addr?: string;
  /** ISP Name: The name of the Internet Service Provider (ISP). (optional) */
  isp?: string;
  /** ISP Org: The organization name of the Internet Service Provider (ISP). This represents the parent organization or company that owns/operates the ISP. For example, Comcast Corporation would be the ISP org for Xfinity internet service. This attribute helps identify the ultimate provider when ISPs operate under different brand names. (optional) */
  isp_org?: string;
  /** Last Updated At: When the WHOIS record was last updated or seen at. (recommended) */
