  /** Last Updated At: When the WHOIS record was last updated or seen at. (optional) */
  last_seen_time_dt?: string;
  /** Name Servers: A collection of name servers related to a domain registration or other record. (recommended) */
  name_servers?: string[];
  /** Registrar Abuse Phone Number: The phone number for the registrar's abuse contact (optional) */
  phone_number?: string;
  /** Domain Registrar: The domain registrar. (recommended) */
  registrar?: string;
  /** Domain Status: The status of a domain and its ability to be transferred, e.g., clientTransferProhibited. (recommended) */
  status?: string;
  /** Subdomains: An array of subdomain strings. Can be used to collect several subdomains such as those from Domain Generation Algorithms (DGAs). (optional) */
