  activity_id: 0 | 1 | 2 | 3 | 99;
  /** Activity: The finding activity name, as defined by the activity_id. When activity_id is 99 (Other), this must contain the source-specific activity label. (optional) */
  activity_name?: string;
  /** Actor: The user, process, or service that initiated the activity on the host. For system-level events this is typically a process; for IAM events it is typically a user or role. (optional) */
  actor?: OcsfActor;
  /** API Details: Describes details about a typical API (Application Programming Interface) call. (optional) */
  api?: OcsfApi;
  /** Assignee: The details of the user assigned to an Incident. (optional) */
  assignee?: OcsfUser;
  /** Assignee Group: The details of the group assigned to an Incident. (optional) */
  assignee_group?: OcsfGroup;
  /** MITRE ATT&CK® and ATLAS™ Details: An array of MITRE ATT&CK® objects describing identified tactics, techniques & sub-techniques. The objects are compatible with MITRE ATLAS™ tactics, techniques & sub-techniques. (optional) */
  attacks?: OcsfAttack[];
  /** Attestation List: One or more cryptographic attestation objects over an event, each providing integrity, authenticity, and non-repudiation. Independent attesters over the same event, for example a producer at write time and a downstream processor at ingest, each contribute a separate attestation, distinct from co-signers on a single attestation, which share its signatures array. Carried on the record_integrity profile; the object itself is domain-agnostic. (optional) */
  attestation_list?: OcsfAttestation[];
  /** Authorization Information: Provides details about an authorization, such as authorization outcome, and any associated policies related to the activity/event. (optional) */
  authorizations?: OcsfAuthorization[];
  /** Category: The event category name, as defined by category_uid value: Findings. (optional) */
  category_name?: string;
  /** Class: The event class name, as defined by class_uid value: Vulnerability Finding. (optional) */
  class_name?: string;
  /** Cloud: Describes details about the Cloud environment where the event or finding was created. (required) */
  cloud?: OcsfCloud;
  /** Comment: A user provided comment about the finding. (optional) */
  comment?: string;
  /** Confidence: The confidence, normalized to the caption of the confidence_id value. In the case of 'Other', it is defined by the event source and should be the same as confidence_score if also populated.. (optional) */
  confidence?: string;
  /** Confidence ID: The normalized confidence refers to the accuracy of the analytics that produced the finding. An analytic with a low confidence means that the finding scope is wide and may create finding reports that are noisy or may not be malicious in nature. Values: 0 Unknown, 1 Low, 2 Medium, 3 High, 99 Other. (recommended) */
  confidence_id?: 0 | 1 | 2 | 3 | 99;
  /** Confidence Score: The confidence score as reported by the event source. If confidence_id is 99 'Other', it should be the same as confidence if both are populated. (optional) */
  confidence_score?: number;
  /** Count: The number of events aggregated into this single record. Only populate for aggregate events. When set, start_time and end_time should also be provided to define the aggregation window. (optional) */
  count?: number;
  /** Device: Describes the affected device/host. It can be used in conjunction with resources or when there are multiple devices affected. E.g. The role of the device as target or actor, specific details about a cloud resource compute instance, etc.If a single device is the source of the finding, use the Host profile and populate device. (optional) */
  device?: OcsfDevice;
  /** Disposition: The disposition name, normalized to the caption of the disposition_id value. In the case of 'Other', it is defined by the event source. (optional) */
  disposition?: string;
