  message?: string;
  /** Metadata: The metadata object describes the event producer, schema version, and processing information. Producers and mappers must populate metadata.product to identify the data source, and metadata.version to indicate the OCSF schema version used. Consumers rely on this to interpret the event correctly. (required) */
  metadata: OcsfMetadata;
  /** Notes: Additional notes related to the finding. Each note in the array can include a comment, the user who made the comment, the time when the note was created, and the time when the note was last modified (typically by the same user). Notes can be used to provide additional context, explanations, or observations by analysts related to the finding over time. (optional) */
  notes?: OcsfNote[];
  /** Observables: The observables array surfaces key indicators and entities from the event or finding in a single, consistent location for downstream correlation and detection. Each entry references an attribute path within the event (e.g., src_endpoint.ip) along with its type and value, enabling consumers to extract IOCs without parsing the full event structure. (recommended) */
  observables?: OcsfObservable[];
  /** OSINT: The OSINT (Open Source Intelligence) object contains details related to an indicator such as the indicator itself, related indicators, geolocation, registrar information, subdomains, analyst commentary, and other contextual information. This information can be used to further enrich a detection or finding by providing decisioning support to other analysts and engineers. (required) */
  osint?: OcsfOsint[];
  /** Policy: The policy that pertains to the control that triggered the event, if applicable. For example the name of an anti-malware policy or an access control policy. (optional) */
  policy?: OcsfPolicy;
  /** Priority: The priority, normalized to the caption of the priority_id value. In the case of 'Other', it is defined by the event source. (optional) */
  priority?: string;
  /** Priority ID: The normalized priority. Priority identifies the relative importance of the incident or finding. It is a measurement of urgency. Values: 0 Unknown, 1 Low, 2 Medium, 3 High, 4 Critical, 99 Other. (recommended) */
  priority_id?: 0 | 1 | 2 | 3 | 4 | 99;
  /** Raw Data: The original event/finding data as received from the source, before normalization into OCSF. Populate this with the verbatim log line, JSON payload, or other native format for forensic and debugging purposes. This field is not intended for structured querying - use the normalized OCSF attributes instead. (optional) */
  raw_data?: string;
  /** Raw Data Hash: A fingerprint (hash) of the raw_data content. Use this to verify the integrity of the original event data or to deduplicate events. (optional) */
  raw_data_hash?: OcsfFingerprint;
  /** Raw Data Size: The size of the original event data (as captured in raw_data) in bytes, before OCSF normalization. Useful for metering and capacity planning. (optional) */
  raw_data_size?: number;
