  resource?: OcsfResourceDetails;
  /** Affected Resources: Describes details about the resource/resources that are affected by the vulnerability/vulnerabilities. (recommended) */
  resources?: OcsfResourceDetails[];
  /** Risk Details: Describes the risk associated with the finding. (optional) */
  risk_details?: string;
