  start_time?: number;
  /** Start Time: The time of the earliest event or finding that contributed to this finding. (optional) */
  start_time_dt?: string;
  /** Status: The finding lifecycle status label, normalized to the caption of the status_id value. When status_id is 99 (Other), this must contain the source-specific status label. (optional) */
  status?: string;
