  status_code?: string;
  /** Status Detail: A human-readable description providing additional context about the event outcome. Use this to convey details that go beyond the normalized status_id and source-specific status_code, such as a failure reason or error message. For example: "Account locked after 5 failed attempts.". (recommended) */
  status_detail?: string;
