  status_id?: 0 | 1 | 2 | 3 | 4 | 5 | 6 | 99;
  /** Ticket: The linked ticket in the ticketing system. (optional) */
  ticket?: OcsfTicket;
  /** Tickets: The associated ticket(s) in the ticketing system. Each ticket contains details like ticket ID, status, etc. (optional) */
  tickets?: OcsfTicket[];
  /** Event Time: The finding creation time - when the finding was first generated, not when the underlying activity occurred. For the time range of contributing events, use start_time and end_time. (required) */
  time: number;
  /** Event Time: The finding creation time - when the finding was first generated, not when the underlying activity occurred. For the time range of contributing events, use start_time and end_time. (optional) */
  time_dt?: string;
